   {
    "title": "Advertencia al lector",
    "chars": 10677
   },
   {
    "title": "Capítulo primero",
    "subtitle": "Mis padres, el lugar de mi nacimiento y mi primera infancia",
    "chars": 10022
   },
   {
    "title": "Capítulo II",
    "subtitle": "Excursión tardía a mi pueblo natal. — La pobreza de mis paisanos. — Un pueblo pobre y aislado que parece símbolo de España",
    "chars": 15299
   },
   {
    "title": "Capítulo III",
    "subtitle": "Mi primera infancia. — Vocación docente de mi padre. — Mi carácter y tendencias. — Admiración por la naturaleza y pasión por los pájaros",
    "chars": 11010
   },
   {
    "title": "Capítulo IV",
    "subtitle": "Mi estancia en Valpalmas. — Los tres acontecimientos decisivos de mi niñez: los festejos destinados a celebrar nuestras victorias de África, la caída de un rayo en la escuela y el eclipse de sol del año 60",
    "chars": 17301
   },
   {
    "title": "Capítulo V",
    "subtitle": "Ayerbe. — Juegos y travesuras de la infancia. — Instintos guerreros y artísticos. — Mis primeras nociones experimentales sobre óptica, balística y el arte de la guerra",
    "chars": 18381
   },
   {
    "title": "Capítulo VI",
    "subtitle": "Desarrollo de mis instintos artísticos. — Dictamen de un revocador sobre mis aptitudes. — ¡Adiós mis ensueños de artista! — Utilitarismo e idealismo. — Decide mi padre hacerme estudiar para médico y enviarme a Jaca",
    "chars": 27513
   },
   {
    "title": "Capítulo VII",
    "subtitle": "Mi traslación a Jaca. — Las pintorescas orillas del Gállego. — Mi tío Juan y el régimen vegetariano. — El latín y los dómines. — Empeño vano de los frailes en domarme. — Retorno a los devaneos artísticos",
    "chars": 12934
   },
   {
    "title": "Capítulo VIII",
    "subtitle": "El padre Jacinto, mi dómine de latín. — Cartagineses y romanos. — El régimen del terror. — Mi aversión al estudio. — Exaltación de mi fiebre artística y romántica. — El río Aragón, símbolo de un pueblo",
    "chars": 17843
   },
   {
    "title": "Capítulo IX",
    "subtitle": "Continúan mis distracciones. — Los encierros y ayunos. — Expedientes usados para escaparme. — Mis exámenes. — Retorno a Ayerbe y vuelta a las andadas",
    "chars": 9818
   },
   {
    "title": "Capítulo X",
    "subtitle": "Mi regreso a Ayerbe. — Nuevas hazañas bélicas. — El cañón de madera. — Tres días de cárcel. — El mosquete simbólico",
    "chars": 12442
   },
   {
    "title": "Capítulo XI",
    "subtitle": "Dispone mi padre llevarme a Huesca a continuar mis estudios. — Exploración de la ciudad. — La catedral, San Pedro, San Jorge y Monte-Aragón. — Nuestros profesores",
    "chars": 17976
   },
   {
    "title": "Capítulo XII",
    "subtitle": "Mis nuevos compañeros de algaradas. — Reyertas estudiantiles. — Graves consecuencias de llevar gabán largo. — Accidente en un estanque. — La religión del color y diccionario cromático. — No hay rosas sin espinas",
    "chars": 24888
   },
   {
    "title": "Capítulo XIII",
    "subtitle": "Las vacaciones. — Pinturas fúnebres. — Descubrimiento de una biblioteca de novelas. — Se recrudece mi furor romántico. — El Robinsón y el Quijote",
    "chars": 16931
   },
   {
    "title": "Capítulo XIV",
    "chars": 21090
   },
   {
    "title": "Capítulo XV",
    "subtitle": "Inquina de mi catedrático de griego. — Decide mi padre escarmentarme convirtiéndome en aprendiz de zapatero. — Mis proezas en obra prima. — El ataque de Linás. — Consideraciones en torno de la muerte",
    "chars": 20958
   },
   {
    "title": "Capítulo XVI",
    "subtitle": "Vuelta al estudio. — Matricúlome en dibujo. — Mis profesores de Retórica y Psicología. — Impresión causada por las enseñanzas filosóficas. — Una travesura desdichada. — En busca de aventuras",
    "chars": 18392
   },
   {
    "title": "Capítulo XVII",
    "subtitle": "Dos inventos que me causaron indecible asombro: el ferrocarril y la fotografía. — Mi iniciación en los estudios anatómicos. — Saqueo macabro. — La memoria de las cosas y la de los libros. — La aurora del amor",
    "chars": 26679
   },
   {
    "title": "Capítulo XVIII",
    "chars": 26874
   },
   {
    "title": "Capítulo XIX",
    "subtitle": "Comienzo en Zaragoza la carrera médica. — El Ebro y sus alamedas. — Mis profesores del preparatorio: Ballarín, Guallart y Solano. — Cobro afición a la disección bajo la dirección docente de mi padre",
    "chars": 19986
   },
   {
    "title": "Capítulo XX",
    "chars": 17443
   },
   {
    "title": "Capítulo XXI",
    "subtitle": "Continúo mis estudios sin grandes mortificaciones. — Mis manías literaria, gimnástica y filosófica. — Proezas musculares. — La Venus de Milo. — Un desafío a trompada limpia. — Amores quijotescos",
    "chars": 23040
   },
   {
    "title": "Capítulo XXII",
    "chars": 23089
   },
   {
    "title": "Capítulo XXIII (1/2)",
    "chars": 21965
   },
   {
    "title": "Capítulo XXIII (2/2)",
    "chars": 21373
   },
   {
    "title": "Capítulo XXIV",
    "chars": 10190
   },
   {
    "title": "Capítulo XXV",
    "subtitle": "Me traslado a la Habana, donde recaigo de mi dolencia. — Mi regreso en el vapor España. — Cadáveres de soldados arrojados al mar. — Tahures trasatlánticos. — El amor y el paludismo. — Vuelta al estudio de la Anatomía",
    "chars": 14516
   }
